 "content": "from collections import Counter, deque


def transform(grid):
    """Restore small corruptions in rectangular color patches; clear stray marks."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    # A real patch color has substantial support; rare colors are corruption marks.
    patch_colors = {c for c, n in counts.items() if c != background and n >= 10}
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in patch_colors or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            boxes.append((min(rs), max(rs), min(cs), max(cs), color))

    # Rare-color cells are noise unless they lie inside a substantive patch's
    # bounding rectangle, where they repair that patch.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or color in patch_colors:
                continue
            matches = [b for b in boxes if b[0] <= r <= b[1] and b[2] <= c <= b[3]]
            if matches:
                # Prefer the tightest rectangle if patches' boxes overlap.
                b = min(matches, key=lambda x: (x[1] - x[0] + 1) * (x[3] - x[2] + 1))
                out[r][c] = b[4]
            else:
                out[r][c] = background
    return out
